-- Auto-generated coordinate fixes for pfQuest-turtle.
-- Source: tortoise-db-viewer (tortoise.sqlite, built 2026-11-11)
-- Loaded after overwrites.lua and before patchtable.lua so ./db remains untouched.
-- Fixes: 50,50 placeholders, city-vs-parent-zone mismatches, shifted 1.18.1/custom coords, and empty coords.

local function set_coords(db_name, id, coords)
  local t_db = pfDB[db_name] and pfDB[db_name]["data-turtle"]
  local b_db = pfDB[db_name] and pfDB[db_name]["data"]
  if t_db and type(t_db[id]) == "table" then
    t_db[id]["coords"] = coords
  elseif b_db and type(b_db[id]) == "table" then
    b_db[id]["coords"] = coords
  elseif t_db then
    t_db[id] = { ["coords"] = coords }
  end
end

